    final map = <String, dynamic>{};
    final metadataValue = metadata;
    if (metadataValue != null) {
      map['metadata'] = metadataValue.toMap();
    }
    final specValue = spec;
    if (specValue != null) {
      map['spec'] = specValue.toMap();
    }
    return map;
  }

  factory RevisionTemplate.fromMap(Map<String, dynamic> map) {
    return RevisionTemplate(
      metadata: map['metadata'] == null
          ? null
          : ObjectMeta.fromMap(
              (map['metadata'] as Map).cast<String, dynamic>()),
      spec: map['spec'] == null
          ? null
          : RevisionSpec.fromMap((map['spec'] as Map).cast<String, dynamic>()),
